 'cash-closing':cashClosing,'bank-import':bankImport,'bank-template'(){download('Top-Hills-Format-Mutasi.csv','date,account,amount,reference\n2026-09-10,1102,150000,MUTASI-FIKTIF-001\n2026-09-10,1102,-50000,MUTASI-FIKTIF-002\n','text/csv');},
